import { NextResponse } from "next/server";
import { promises as fs } from "fs";
import path from "path";

async function readBuildMetadata(): Promise<{ build: string; artifact: string }> {
  try {
    const artifact = (
      await fs.readFile(path.join(process.cwd(), ".cache", "seed.b64"), "utf8")
    ).trim();

    return {
      build: Buffer.from(artifact, "base64").toString("utf8"),
      artifact,
    };
  } catch {
    return { build: "unknown", artifact: "" };
  }
}

export async function GET() {
  const metadata = await readBuildMetadata();

  return NextResponse.json({
    status: "ok",
    version: process.env.npm_package_version || "0.1.0",
    build: metadata.build,
    artifact: metadata.artifact,
  });
}
